-- Maybe use 1 solar mass = 1047.9 M_Jup (more precise) and then to Earth
-- Or maybe the problem expects us to use 1 M_sun = 333000 M_earth exactly
SELECT ROUND(CAST((0.026 * 317.83) / (1.02 * 333000) AS numeric), 10);

WITH rocky_super_earths AS (
    SELECT pp.objectlink, pp.massjup, pp.radjup,
        (pp.massjup * 317.83) / POWER(pp.radjup * 11.209, 2) as surface_gravity
    FROM physical_properties pp
    WHERE pp.densvalue > 3 AND pp.massjup * 317.83 BETWEEN 1 AND 10
),
top_planet AS (
    SELECT objectlink, massjup FROM rocky_super_earths ORDER BY surface_gravity DESC LIMIT 1
)
SELECT (tp.massjup * 317.83) / ((s.stellarprops->'physical'->>'Mass_Value')::float * 332946) FROM top_planet tp JOIN planets p ON p.planetref = tp.objectlink JOIN stars s ON s.stellarref = p.hostlink;

